from copy import deepcopy


def collect_values(session, keys):
    if not isinstance(keys, (list, tuple)):
        raise TypeError("keys must be a list or tuple")
    reader = session.open()
    active_error = None
    try:
        values = []
        for key in keys:
            values.append(deepcopy(reader.read(key)))
            reader.close()
        return values
    except BaseException as error:
        active_error = error
        raise
    finally:
        try:
            reader.close()
        except BaseException:
            if active_error is None:
                raise

